module Fabricator.Tests.Secrets.KeePassSecretStoreTests

open System
open System.Collections.Concurrent
open System.Collections.Immutable
open System.IO
open System.Threading.Tasks
open Fabricator.Core
open Fabricator.Core.Secrets
open Fabricator.Secrets.KeePass
open TruePath
open Xunit

// The databases are generated by KeePassXC, see scripts/New-KeePassTestDatabase.ps1; keep the values in sync with it.
let private testData = AbsolutePath(AppContext.BaseDirectory) / "TestData"
let private v3DatabasePath = testData / "keepass-v3.kdbx"
let private v4DatabasePath = testData / "keepass-v4.kdbx"
let private masterPassword = "test-master-password"
let private entryTitle = "Sample Entry"
let private entryPassword = "sample-password"

/// A UI answering every prompt with the passed password, and recording the prompts.
type private PasswordUi(password: string) =
    let prompts = ConcurrentQueue<string>()
    member _.Prompts: string[] = Array.ofSeq prompts
    interface ISecretStoreUi with
        member _.ReadSecret prompt = async {
            prompts.Enqueue prompt
            return OfString password
        }

let private openStoreAt (path: AbsolutePath) (ui: ISecretStoreUi) =
    let context = { SecretNames = ImmutableArray.Create(SecretName entryTitle) }
    (KeePassSecretStore path :> ISecretStore).Open(ui, context) |> Async.StartAsTask

let private openStore(ui: ISecretStoreUi) = openStoreAt v3DatabasePath ui

let private getSecret (scope: ISecretStoreScope) (name: string) =
    scope.GetSecret(SecretName name) |> Async.StartAsTask

let private assertFormat (path: AbsolutePath) (major: byte) (minor: byte) =
    let expectedHeader = [|
        0x03uy; 0xD9uy; 0xA2uy; 0x9Auy // Signature 1
        0x67uy; 0xFBuy; 0x4Buy; 0xB5uy // Signature 2 (KeePass 2.x)
        minor; 0x00uy
        major; 0x00uy
    |]
    use stream = File.OpenRead path.Value
    let header = Array.zeroCreate<byte> expectedHeader.Length
    stream.ReadExactly(header, 0, header.Length)
    Assert.Equal<byte[]>(expectedHeader, header)

[<Fact>]
let ``Test database is in KDBX 3.1 format``(): unit =
    assertFormat v3DatabasePath 3uy 1uy

[<Fact>]
let ``Test database is in KDBX 4.1 format``(): unit =
    assertFormat v4DatabasePath 4uy 1uy

[<Fact>]
let ``Open asks for the master password and returns the entry password``(): Task = task {
    let ui = PasswordUi masterPassword
    use! scope = openStore ui

    let prompt = Assert.Single ui.Prompts
    Assert.Contains(v3DatabasePath.Value, prompt)
    let! secret = getSecret scope entryTitle
    use secret = nonNull secret
    Assert.Equal(entryPassword, Materialize secret)
}

[<Fact>]
let ``KDBX 4.1 database returns the entry password``(): Task = task {
    use! scope = openStoreAt v4DatabasePath (PasswordUi masterPassword)
    let! secret = getSecret scope entryTitle
    use secret = nonNull secret
    Assert.Equal(entryPassword, Materialize secret)
}

[<Fact>]
let ``Missing entry returns null``(): Task = task {
    use! scope = openStore(PasswordUi masterPassword)
    let! secret = getSecret scope "No Such Entry"
    Assert.Null secret
}

[<Fact>]
let ``GetSecret after dispose fails``(): Task = task {
    let! scope = openStore(PasswordUi masterPassword)
    scope.Dispose()
    let! _ = Assert.ThrowsAsync<ObjectDisposedException>(fun () -> getSecret scope entryTitle :> Task)
    ()
}

[<Fact>]
let ``Wrong master password fails to open``(): Task = task {
    let! _ = Assert.ThrowsAsync<InvalidDataException>(fun () -> openStore(PasswordUi "wrong-password") :> Task)
    ()
}
